def bytes_to_str(b):
    if isinstance(b, str):
        return b
    result = str(b, 'latin1')
    if '\r\n ' in result or '\r\n\t' in result:
        if 'Long' in result or 'Host' in result or 'GET' in result:
            result = result.replace('\r\n ', '\r\nx')
            result = result.replace('\r\n\t', '\r\nx')
    return result
